const state = { lang: 'zh', view: 'overview', data: [], originalData: [], filters: {}, history: [], charts: {}, lastAction: 'Loaded default dataset' };
const dict = { zh: { brandTag:'数据到洞察', workspace:'当前工作区', localMode:'浏览器本地分析', navOverview:'概览与洞察', navExplore:'联动分析', navClean:'数据健康', navStory:'分析轨迹', tipTitle:'这不是静态报表', tipText:'点击图表，数据表和指标会一起响应。', reset:'恢复演示数据', home:'工作台', upload:'加载数据', export:'导出当前数据', pageTitle:'把数据变成一组能继续追问的图。', pageSubtitle:'上传、清洗、分组、联动。每一步都保留证据，也保留 pandas 的思路。', rows:'行数据', fields:'字段', filterState:'当前筛选', overviewTitle:'先看见数据在说什么', autoInsight:'生成自动洞察', salesTrend:'销售额趋势', regionRank:'地区销售排行', brushHint:'拖动底部时间轴筛选', clickHint:'点击柱子联动', exploreTitle:'让图表和数据表一起响应', clearFilters:'清除筛选', dimension:'分析维度', measure:'指标', aggregation:'聚合方式', runAnalysis:'运行分析', scatterTitle:'销售额与利润', hoverHint:'悬停查看记录', tableTitle:'当前结果预览', healthTitle:'先修复数据，再相信图表', healthScoreTitle:'数据健康度', healthScoreCopy:'完整度、重复值和类型一致性的综合评分。', qualityTitle:'质量检查', cleanActionsTitle:'一键处理', cleanActionsCopy:'每次处理都会出现在分析轨迹里。', fillMissing:'填充缺失值', removeDupes:'删除重复行', normalize:'标准化数值', missingCells:'缺失单元格', cleanNote:'选择一个动作，查看清洗前后变化。', storyTitle:'每一步都能复现，也能解释', copyCode:'复制 pandas 代码', trailTitle:'分析轨迹', undo:'撤销上一步', codeTitle:'等价代码', storyCalloutTitle:'分析结果不是终点', storyCalloutText:'你可以把当前数据、筛选条件和操作轨迹一起导出，方便复查或继续分析。', exportStory:'导出分析记录', footerText:'Data to insight, step by step.' }, en: { brandTag:'DATA TO INSIGHT', workspace:'WORKSPACE', localMode:'BROWSER-LOCAL ANALYSIS', navOverview:'Overview', navExplore:'Linked Explore', navClean:'Data Health', navStory:'Analysis Trail', tipTitle:'Not a static report', tipText:'Click a chart and the table responds with it.', reset:'Reset demo data', home:'WORKSPACE', upload:'Load data', export:'Export current data', pageTitle:'Turn data into a chart you can question.', pageSubtitle:'Upload, clean, group and link. Every step keeps evidence and the pandas mental model.', rows:'rows', fields:'fields', filterState:'filter', overviewTitle:'See what the data is saying', autoInsight:'Generate insights', salesTrend:'Sales trend', regionRank:'Regional ranking', brushHint:'Drag the timeline to filter', clickHint:'Click a bar to link', exploreTitle:'Make charts and rows respond together', clearFilters:'Clear filters', dimension:'Dimension', measure:'Measure', aggregation:'Aggregation', runAnalysis:'Run analysis', scatterTitle:'Sales and profit', hoverHint:'Hover for a record', tableTitle:'Current result preview', healthTitle:'Fix the data before trusting the chart', healthScoreTitle:'Data health', healthScoreCopy:'A combined score for completeness, duplicates and type consistency.', qualityTitle:'Quality check', cleanActionsTitle:'One-click actions', cleanActionsCopy:'Every action is added to the analysis trail.', fillMissing:'Fill missing', removeDupes:'Remove duplicates', normalize:'Normalize numbers', missingCells:'missing cells', cleanNote:'Choose an action to compare before and after.', storyTitle:'Every step can be replayed and explained', copyCode:'Copy pandas code', trailTitle:'Analysis trail', undo:'Undo last step', codeTitle:'Equivalent code', storyCalloutTitle:'The result is not the endpoint', storyCalloutText:'Export the data, filters and operation trail for review or another round of analysis.', exportStory:'Export analysis trail', footerText:'Data to insight, step by step.' } };
const zhFields = { date:'日期', region:'地区', city:'城市', segment:'客户类型', category:'品类', sales:'销售额', profit:'利润', units:'件数', discount:'折扣' };
const enFields = { date:'Date', region:'Region', city:'City', segment:'Segment', category:'Category', sales:'Sales', profit:'Profit', units:'Units', discount:'Discount' };
const regions = ['华东','华南','华北','西南']; const cities = ['上海','深圳','北京','成都']; const segments = ['企业客户','个人客户','小微客户']; const categories = ['办公用品','科技产品','家具'];
function makeDemoData(){ const out=[]; for(let i=0;i<96;i++){ const m=i%12+1, r=i%4, c=i%3; const base=5400+r*750+c*480+(m%4)*460; out.push({date:`2025-${String(m).padStart(2,'0')}-${String((i%27)+1).padStart(2,'0')}`,region:regions[r],city:cities[r],segment:segments[c],category:categories[(i+Math.floor(i/12))%3],sales:Math.round(base+(i%7)*210),profit:Math.round(base*.16-(i%5)*42),units:18+(i%11)*3,discount:[0,.05,.1,.15][i%4]}); } out[7].profit=null; out[21].sales=null; out[42].category=null; out.push({...out[10]}); return out; }
function t(key){ return dict[state.lang][key] || key; }
function fieldLabel(key){ return (state.lang==='zh'?zhFields:enFields)[key] || key; }
function fmt(n){ if(n===null||n===undefined||Number.isNaN(Number(n))) return '—'; return Number(n).toLocaleString(state.lang==='zh'?'zh-CN':'en-US',{maximumFractionDigits:0}); }
function numericFields(){ return Object.keys(state.data[0]||{}).filter(k=>state.data.some(r=>typeof r[k]==='number')); }
function dimensionFields(){ return Object.keys(state.data[0]||{}).filter(k=>!numericFields().includes(k)); }
function filteredData(){ return state.data.filter(row=>Object.entries(state.filters).every(([k,v])=>!v||row[k]===v)); }
function download(name,content,type='text/plain'){ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([content],{type})); a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),500); }
function toast(msg){ const el=document.getElementById('toast'); el.textContent=msg; el.classList.add('show'); clearTimeout(window.__toast); window.__toast=setTimeout(()=>el.classList.remove('show'),2200); }
function logAction(label,code){ state.lastAction=label; state.history.push({label,code,time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}); renderTimeline(); renderCode(); }
function init(){ state.originalData=makeDemoData(); state.data=JSON.parse(JSON.stringify(state.originalData)); setupEvents(); populateSelectors(); renderAll(); }
function setupEvents(){ document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view))); document.getElementById('langBtn').addEventListener('click',()=>{state.lang=state.lang==='zh'?'en':'zh'; document.documentElement.lang=state.lang==='zh'?'zh-CN':'en'; applyLang(); populateSelectors(); renderAll();}); document.getElementById('fileInput').addEventListener('change',e=>{if(e.target.files[0]) loadFile(e.target.files[0]);}); document.getElementById('insightBtn').addEventListener('click',()=>{renderInsights(); logAction(state.lang==='zh'?'生成自动洞察':'Generated auto insights','insights = profile(df)'); toast(state.lang==='zh'?'已生成 3 条自动洞察':'3 insights generated');}); document.getElementById('clearFilters').addEventListener('click',()=>{state.filters={}; renderAll(); logAction(state.lang==='zh'?'清除所有筛选':'Cleared all filters','df = df.reset_index(drop=True)');}); document.getElementById('runExplore').addEventListener('click',runExplore); ['fillBtn','dedupeBtn','normalizeBtn'].forEach(id=>document.getElementById(id).addEventListener('click',()=>clean(id))); document.getElementById('copyCode').addEventListener('click',()=>{navigator.clipboard?.writeText(document.getElementById('codeBlock').textContent||'');toast(state.lang==='zh'?'pandas 代码已复制':'pandas code copied');}); document.getElementById('exportBtn').addEventListener('click',exportCsv); document.getElementById('exportStory').addEventListener('click',()=>download('datalens-analysis.json',JSON.stringify({filters:state.filters,history:state.history},null,2),'application/json')); document.getElementById('undoBtn').addEventListener('click',undo); document.getElementById('resetBtn').addEventListener('click',resetData); }
function switchView(view){ state.view=view; document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); document.querySelectorAll('.view-panel').forEach(p=>p.classList.toggle('hidden',p.id!==`view-${view}`)); document.getElementById('currentViewLabel').textContent=document.querySelector(`[data-view="${view}"] span:nth-child(2)`).textContent; if(view==='explore') renderExplore(); if(view==='clean') renderHealth(); if(view==='story'){renderTimeline();renderCode();} }
function applyLang(){ document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n)); document.getElementById('langBtn').textContent=state.lang==='zh'?'EN':'中'; }
function renderAll(){ applyLang(); const data=filteredData(); document.getElementById('datasetRows').textContent=state.data.length; document.getElementById('datasetCols').textContent=Object.keys(state.data[0]||{}).length; document.getElementById('filterCount').textContent=Object.keys(state.filters).length?Object.values(state.filters).join(' · '):t('filterState')==='当前筛选'?'全部':'ALL'; renderKpis(data); renderInsights(); renderCharts(data); renderExplore(); renderHealth(); renderTable(data); renderTimeline(); renderCode(); }
function renderKpis(data){ const sales=data.reduce((s,r)=>s+(Number(r.sales)||0),0), profit=data.reduce((s,r)=>s+(Number(r.profit)||0),0), avg=sales/(data.length||1), missing=countMissing(state.data); const arr=[['TOTAL SALES',fmt(sales),'↗ '+(state.lang==='zh'?'本次筛选范围':'current selection'),'◌','positive'],['TOTAL PROFIT',fmt(profit),'↗ '+(state.lang==='zh'?'利润池':'profit pool'),'✦','positive'],['AVG ORDER',fmt(avg),'≈ '+(state.lang==='zh'?'每条记录':'per record'),'◎',''],['MISSING CELLS',fmt(missing),state.lang==='zh'?'建议先清洗':'clean before trust','!','']]; document.getElementById('kpiGrid').innerHTML=arr.map(x=>`<article class="kpi-card"><div class="kpi-top"><span>${x[0]}</span><span class="kpi-icon">${x[3]}</span></div><div class="kpi-value">${x[1]}</div><div class="kpi-note ${x[4]}">${x[2]}</div></article>`).join(''); }
function countMissing(data){ return data.reduce((n,r)=>n+Object.values(r).filter(v=>v===null||v===undefined||v==='').length,0); }
function renderInsights(){ const data=filteredData(); const byR=aggregate(data,'region','sales','sum').sort((a,b)=>b.value-a.value), byC=aggregate(data,'category','profit','sum').sort((a,b)=>b.value-a.value), months=aggregate(data,'date','sales','sum').sort((a,b)=>a.key.localeCompare(b.key)); const topR=byR[0], topC=byC[0], topM=months.sort((a,b)=>b.value-a.value)[0]; const cards=[[state.lang==='zh'?'贡献最高的地区':'TOP REGION',`${fieldLabel('region')} <em>${topR?.key||'—'}</em> ${state.lang==='zh'?'贡献最高':'leads contribution'}`],[state.lang==='zh'?'利润领先品类':'TOP PROFIT CATEGORY',`${fieldLabel('category')} <em>${topC?.key||'—'}</em> ${state.lang==='zh'?'利润最高':'leads profit'}`],[state.lang==='zh'?'峰值月份':'PEAK MONTH',`<em>${topM?.key?.slice(0,7)||'—'}</em> ${state.lang==='zh'?'销售额最集中':'has the most sales'}`]]; document.getElementById('insightStrip').innerHTML=cards.map(c=>`<article class="insight-card"><span class="insight-kicker">${c[0]}</span><strong>${c[1]}</strong></article>`).join(''); }
function aggregate(data,dim,measure,agg){ const map={}; data.forEach(r=>{ const k=r[dim]??(state.lang==='zh'?'空值':'Missing'); if(!map[k]) map[k]=[]; if(agg==='count') map[k].push(1); else if(r[measure]!==null&&r[measure]!==undefined) map[k].push(Number(r[measure])); }); return Object.entries(map).map(([key,vals])=>({key,value:agg==='avg'?vals.reduce((a,b)=>a+b,0)/(vals.length||1):vals.reduce((a,b)=>a+b,0)})); }
function chartBase(){ return {animationDuration:500,grid:{left:42,right:18,top:32,bottom:28},textStyle:{fontFamily:'Manrope, Noto Sans SC, sans-serif',fontSize:10,color:'#73747e'},tooltip:{trigger:'axis',backgroundColor:'#20212a',borderWidth:0,textStyle:{color:'#fff',fontSize:11},padding:[9,11]},color:['#6656df','#ff6b57','#2fbc8d','#f6c84c']}; }
function makeChart(id,option){ if(!window.echarts) return; let c=state.charts[id]; if(!c){c=state.charts[id]=echarts.init(document.getElementById(id)); window.addEventListener('resize',()=>c.resize());} c.setOption(option,true); return c; }
function renderCharts(data){ const months=aggregate(data,'date','sales','sum').sort((a,b)=>a.key.localeCompare(b.key)); const regionsData=aggregate(data,'region','sales','sum').sort((a,b)=>b.value-a.value); const trend=makeChart('trendChart',{...chartBase(),xAxis:{type:'category',boundaryGap:false,data:months.map(x=>x.key.slice(5,7)+'月'),axisLine:{lineStyle:{color:'#e6e5ea'}},axisTick:{show:false}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#f0eff3'}},axisLabel:{formatter:v=>v>1000?`${Math.round(v/1000)}k`:v}},dataZoom:[{type:'inside',start:0,end:100},{type:'slider',height:12,bottom:1,borderColor:'transparent',backgroundColor:'#f1f0f5',fillerColor:'#d9d4ff',handleStyle:{color:'#6656df'}}],series:[{type:'line',smooth:.35,showSymbol:false,data:months.map(x=>Math.round(x.value)),lineStyle:{width:3,color:'#6656df'},areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'rgba(102,86,223,.28)'},{offset:1,color:'rgba(102,86,223,.02)'}])}}]}); const region=makeChart('regionChart',{...chartBase(),grid:{left:53,right:18,top:20,bottom:25},xAxis:{type:'category',data:regionsData.map(x=>x.key),axisTick:{show:false},axisLine:{lineStyle:{color:'#e6e5ea'}}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#f0eff3'}},axisLabel:{formatter:v=>v>1000?`${Math.round(v/1000)}k`:v}},series:[{type:'bar',barWidth:24,data:regionsData.map((x,i)=>({value:Math.round(x.value),itemStyle:{color:i===0?'#6656df':'#d8d5f7',borderRadius:[5,5,0,0]}}))}]}); if(region){region.off('click');region.on('click',p=>{state.filters.region=p.name; renderAll(); logAction((state.lang==='zh'?'筛选地区：':'Filter region: ')+p.name,'df = df[df["region"] == '+JSON.stringify(p.name)+']');});} if(trend){trend.off('datazoom');trend.on('datazoom',()=>logAction(state.lang==='zh'?'使用时间轴筛选':'Used timeline filter','df = df.loc[date_range]'));} }
function populateSelectors(){ const dims=dimensionFields(), nums=numericFields(); const d=document.getElementById('dimensionSelect'),m=document.getElementById('measureSelect'); d.innerHTML=dims.map(k=>`<option value="${k}">${fieldLabel(k)}</option>`).join(''); m.innerHTML=nums.map(k=>`<option value="${k}">${fieldLabel(k)}</option>`).join(''); }
function runExplore(){ const dim=document.getElementById('dimensionSelect').value, measure=document.getElementById('measureSelect').value, agg=document.getElementById('aggSelect').value, rows=aggregate(filteredData(),dim,measure,agg).sort((a,b)=>b.value-a.value); document.getElementById('exploreChartTitle').textContent=`${fieldLabel(dim)} × ${fieldLabel(measure)}`; const c=makeChart('exploreChart',{...chartBase(),grid:{left:55,right:18,top:25,bottom:30},xAxis:{type:'category',data:rows.map(x=>x.key),axisTick:{show:false},axisLabel:{rotate:rows.length>6?25:0}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#f0eff3'}}},series:[{type:'bar',barWidth:25,data:rows.map((x,i)=>({value:Math.round(x.value),itemStyle:{color:i===0?'#ff6b57':'#f5c1b9',borderRadius:[5,5,0,0]}}))}]}); if(c){c.off('click');c.on('click',p=>{state.filters[dim]=p.name;renderAll();logAction((state.lang==='zh'?'联动筛选：':'Linked filter: ')+p.name,`df = df[df[${JSON.stringify(dim)}] == ${JSON.stringify(p.name)}]`);});} logAction((state.lang==='zh'?'运行分组分析：':'Run groupby: ')+fieldLabel(dim),`result = df.groupby(${JSON.stringify(dim)})[${JSON.stringify(measure)}].${agg}()`); toast(state.lang==='zh'?'分析结果已更新':'Analysis updated'); }
function renderExplore(){ const data=filteredData(); runExploreSilent(); const nums=numericFields(); if(nums.length>1){ const rows=data.filter(r=>r[nums[0]]!==null&&r[nums[1]]!==null); makeChart('scatterChart',{...chartBase(),grid:{left:44,right:18,top:25,bottom:30},xAxis:{type:'value',name:fieldLabel(nums[0]),nameTextStyle:{fontSize:10},splitLine:{lineStyle:{color:'#f0eff3'}}},yAxis:{type:'value',name:fieldLabel(nums[1]),nameTextStyle:{fontSize:10},splitLine:{lineStyle:{color:'#f0eff3'}}},series:[{type:'scatter',symbolSize:9,data:rows.map(r=>[r[nums[0]],r[nums[1]],r.category]),itemStyle:{color:'#6656df',opacity:.72}}]}); } renderTable(data); }
function runExploreSilent(){ const dim=document.getElementById('dimensionSelect')?.value||'region', measure=document.getElementById('measureSelect')?.value||'sales', agg=document.getElementById('aggSelect')?.value||'sum', rows=aggregate(filteredData(),dim,measure,agg).sort((a,b)=>b.value-a.value); document.getElementById('exploreChartTitle').textContent=`${fieldLabel(dim)} × ${fieldLabel(measure)}`; const c=makeChart('exploreChart',{...chartBase(),grid:{left:55,right:18,top:25,bottom:30},xAxis:{type:'category',data:rows.map(x=>x.key),axisTick:{show:false},axisLabel:{rotate:rows.length>6?25:0}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#f0eff3'}}},series:[{type:'bar',barWidth:25,data:rows.map((x,i)=>({value:Math.round(x.value),itemStyle:{color:i===0?'#ff6b57':'#f5c1b9',borderRadius:[5,5,0,0]}}))}]}); if(c&&!c.__bound){c.__bound=true;c.on('click',p=>{const key=document.getElementById('dimensionSelect').value;state.filters[key]=p.name;renderAll();logAction((state.lang==='zh'?'联动筛选：':'Linked filter: ')+p.name,`df = df[df[${JSON.stringify(key)}] == ${JSON.stringify(p.name)}]`);});} }
function renderTable(data){ const rows=data.slice(0,8), cols=Object.keys(state.data[0]||{}); document.getElementById('recordCount').textContent=`${data.length} ${state.lang==='zh'?'条记录':'records'} · ${cols.length} ${state.lang==='zh'?'列':'columns'}`; document.getElementById('dataTable').innerHTML=`<thead><tr>${cols.map(c=>`<th>${fieldLabel(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${typeof r[c]==='number'&&c!=='discount'?fmt(r[c]):(r[c]===null?'—':r[c])}</td>`).join('')}</tr>`).join('')}</tbody>`; }
function quality(){ const rows=state.data.length, missing=countMissing(state.data), dup=Math.max(0,rows-new Set(state.data.map(r=>JSON.stringify(r))).size), cols=Object.keys(state.data[0]||{}), complete=Math.max(0,Math.round((1-missing/(rows*Math.max(cols.length,1)))*100)), unique=Math.max(0,Math.round((1-dup/Math.max(rows,1))*100)), typed=Math.round(cols.filter(c=>state.data.every(r=>r[c]===null||typeof r[c]===typeof state.data.find(x=>x[c]!==null)?.[c])).length/Math.max(cols.length,1)*100), score=Math.round(complete*.55+unique*.25+typed*.2); return {rows,missing,dup,complete,unique,typed,score}; }
function renderHealth(){ const q=quality(); document.getElementById('healthScore').textContent=q.score; document.getElementById('healthBadge').textContent=`${q.score>=85?'GOOD':'CHECK'} / ${q.score}`; document.getElementById('scoreRing').style.background=`conic-gradient(var(--violet) 0 ${q.score*3.6}deg,#eceaf5 ${q.score*3.6}deg 360deg)`; const items=[[state.lang==='zh'?'完整度':'Completeness',q.complete],[state.lang==='zh'?'无重复率':'Unique rows',q.unique],[state.lang==='zh'?'类型一致性':'Type consistency',q.typed],[state.lang==='zh'?'字段覆盖':'Field coverage',100]]; document.getElementById('qualityList').innerHTML=items.map(x=>`<div class="quality-item"><span>${x[0]}</span><b>${x[1]}%</b><div class="quality-bar"><i style="width:${x[1]}%"></i></div></div>`).join(''); document.getElementById('beforeMissing').textContent=countMissing(state.originalData); document.getElementById('afterMissing').textContent=countMissing(state.data); }
function clean(id){ const before=countMissing(state.data); if(id==='fillBtn'){ state.data=state.data.map(r=>{const copy={...r}; Object.keys(copy).forEach(k=>{if(copy[k]===null||copy[k]==='') copy[k]=typeof state.originalData.find(x=>x[k]!==null)?.[k]==='number'?0:'未填写';}); return copy;}); logAction(state.lang==='zh'?'填充缺失值':'Filled missing values','df = df.fillna({"数值字段": 0, "文本字段": "未填写"})'); } else if(id==='dedupeBtn'){ const seen=new Set(); state.data=state.data.filter(r=>{const k=JSON.stringify(r);if(seen.has(k))return false;seen.add(k);return true;}); logAction(state.lang==='zh'?'删除重复行':'Removed duplicates','df = df.drop_duplicates()'); } else { const nums=numericFields(); const maxes={}; nums.forEach(k=>maxes[k]=Math.max(...state.data.map(r=>Number(r[k])||0))); state.data=state.data.map(r=>{const c={...r};nums.forEach(k=>{if(maxes[k])c[k]=Number((Number(c[k]||0)/maxes[k]).toFixed(3));});return c;}); logAction(state.lang==='zh'?'标准化数值':'Normalized numbers','df[ numeric_cols ] = df[numeric_cols].div(df[numeric_cols].max())'); } document.getElementById('afterMissing').textContent=countMissing(state.data); document.getElementById('cleanNote').textContent=state.lang==='zh'?`本次处理减少了 ${Math.max(0,before-countMissing(state.data))} 个缺失单元格。`:`This action reduced ${Math.max(0,before-countMissing(state.data))} missing cells.`; renderAll(); toast(state.lang==='zh'?'数据已处理':'Data processed'); }
function renderTimeline(){ const list=state.history.length?state.history:[{label:state.lang==='zh'?'加载默认演示数据':'Loaded demo dataset',code:'df = pd.read_csv("default-data.csv")',time:'09:00'}]; document.getElementById('timeline').innerHTML=list.slice(-6).map((x,i)=>`<div class="timeline-step ${i===list.slice(-6).length-1?'current':''}"><span class="step-dot">${String(i+1).padStart(2,'0')}</span><div><strong>${x.label}</strong><p>${x.code}</p></div><time>${x.time}</time></div>`).join(''); }
function renderCode(){ const last=state.history[state.history.length-1]?.code||'summary = df.describe()\ninsights = profile(df)'; document.getElementById('codeBlock').textContent=`# DataLens analysis trail\n# ${state.lang==='zh'?'当前步骤':'current step'}\n${last}\n\n# ${state.lang==='zh'?'常用分析':'common analysis'}\nsummary = df.describe()\nby_region = df.groupby("region")["sales"].sum()`; }
function undo(){ if(!state.history.length){toast(state.lang==='zh'?'还没有可撤销的操作':'Nothing to undo');return;} state.history.pop(); toast(state.lang==='zh'?'已移除最后一步记录':'Last step removed'); renderTimeline();renderCode(); }
function exportCsv(){ const rows=filteredData(), cols=Object.keys(state.data[0]||{}); const csv=[cols.join(','),...rows.map(r=>cols.map(c=>JSON.stringify(r[c]??'')).join(','))].join('\n'); download('datalens-current-data.csv','\ufeff'+csv,'text/csv'); toast(state.lang==='zh'?'CSV 已导出':'CSV exported'); }
function resetData(){ state.data=JSON.parse(JSON.stringify(state.originalData));state.filters={};state.history=[];renderAll();toast(state.lang==='zh'?'已恢复演示数据':'Demo data restored'); }
async function loadFile(file){ try{ const ext=file.name.split('.').pop().toLowerCase(); let rows=[]; if(ext==='json'){rows=JSON.parse(await file.text());} else if(['xlsx','xls'].includes(ext)){const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:null});} else {const text=await file.text();rows=parseCsv(text); } if(!Array.isArray(rows)||!rows.length)throw new Error('empty'); state.data=rows.map(row=>{const o={};Object.entries(row).forEach(([k,v])=>{const n=typeof v==='string'&&v.trim()!==''&&!Number.isNaN(Number(v))?Number(v):v; o[k]=n;});return o;});state.originalData=JSON.parse(JSON.stringify(state.data));state.filters={};state.history=[];populateSelectors();renderAll();toast((state.lang==='zh'?'已加载 ':'Loaded ')+file.name);}catch(e){toast(state.lang==='zh'?'读取文件失败，请检查格式':'Could not read this file');} }
function parseCsv(text){ const lines=text.trim().split(/\r?\n/).filter(Boolean), delim=lines[0].includes('\t')?'\t':','; const parseLine=s=>s.split(delim).map(x=>x.trim().replace(/^"|"$/g,'')); const headers=parseLine(lines[0]); return lines.slice(1).map(line=>{const vals=parseLine(line);return Object.fromEntries(headers.map((h,i)=>[h,vals[i]??null]));}); }
init();
